export type ReportKind = 'review' | 'forward' | 'book' | 'corpus';

const isObj = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

const missing = (v: unknown) => v === undefined || v === null;

function requireFields(obj: unknown, path: string, fields: string[], errors: string[]): void {
  if (!isObj(obj)) {
    errors.push(`${path}: expected object`);
    return;
  }
  for (const f of fields) {
    if (missing(obj[f])) errors.push(`${path}.${f}: missing`);
  }
}

function requireArray(
  data: Record<string, unknown>,
  key: string,
  itemFields: string[],
  errors: string[],
): void {
  const path = `data.${key}`;
  const arr = data[key];
  if (missing(arr)) {
    errors.push(`${path}: missing`);
    return;
  }
  if (!Array.isArray(arr)) {
    errors.push(`${path}: expected array`);
    return;
  }
  arr.forEach((item, i) => requireFields(item, `${path}[${i}]`, itemFields, errors));
}

export function validateReport(
  kind: ReportKind,
  json: unknown,
): { ok: boolean; errors: string[] } {
  const errors: string[] = [];
  if (!isObj(json)) return { ok: false, errors: ['$: expected object'] };

  if (json.schemaVersion !== 1) errors.push('schemaVersion: expected 1');

  const data = json.data;
  if (missing(data)) {
    errors.push('data: missing');
  } else if (!isObj(data)) {
    errors.push('data: expected object');
  } else {
    switch (kind) {
      case 'review':
        if (missing(data.repo)) errors.push('data.repo: missing');
        requireArray(data, 'setups', ['id'], errors);
        break;
      case 'forward':
        requireArray(data, 'pairs', ['task', 'passOld', 'passNew'], errors);
        break;
      case 'book':
        requireArray(data, 'department', [], errors);
        break;
      case 'corpus':
        requireArray(data, 'rows', [], errors);
        if (missing(data.totals)) errors.push('data.totals: missing');
        break;
      default:
        errors.push(`kind: unknown "${String(kind)}"`);
    }
  }
  return { ok: errors.length === 0, errors };
}
EOF
cat > tests/report-validate.test.ts <<'EOF'
import { describe, expect, test } from 'bun:test';
import { validateReport } from '../src/report/validate';

describe('validateReport', () => {
  test('accepts valid reports of each kind', () => {
    expect(validateReport('review', { schemaVersion: 1, data: { repo: 'a/b', setups: [{ id: 'A' }] } }).ok).toBe(true);
    expect(validateReport('forward', { schemaVersion: 1, data: { pairs: [{ task: 't', passOld: true, passNew: false }] } }).ok).toBe(true);
    expect(validateReport('book', { schemaVersion: 1, data: { department: [] } }).ok).toBe(true);
    expect(validateReport('corpus', { schemaVersion: 1, data: { rows: [], totals: {} } }).ok).toBe(true);
  });

  test('rejects non-objects and bad schemaVersion', () => {
    expect(validateReport('book', null).ok).toBe(false);
    const r = validateReport('book', { schemaVersion: 2, data: { department: [] } });
    expect(r.ok).toBe(false);
    expect(r.errors).toContain('schemaVersion: expected 1');
  });

  test('reports JSON-path errors', () => {
    const r = validateReport('review', { schemaVersion: 1, data: { setups: [{ id: 'a' }, { id: 'b' }, {}] } });
    expect(r.errors).toEqual(['data.repo: missing', 'data.setups[2].id: missing']);
  });

  test('forward pair fields; false passOld is not missing', () => {
    const r = validateReport('forward', { schemaVersion: 1, data: { pairs: [{ task: 't', passOld: false }] } });
    expect(r.errors).toEqual(['data.pairs[0].passNew: missing']);
  });

  test('missing data and corpus fields', () => {
    expect(validateReport('forward', { schemaVersion: 1 }).errors).toEqual(['data: missing']);
    expect(validateReport('corpus', { schemaVersion: 1, data: {} }).errors).toEqual(['data.rows: missing', 'data.totals: missing']);
    expect(validateReport('book', { schemaVersion: 1, data: { department: {} } }).errors).toEqual(['data.department: expected array']);
  });
});
EOF
